begin;
create extension if not exists pgtap with schema public;
select no_plan();
select columns_are('live_read','team_members',array['id','name','email'],'PRD team member projection contains only identity, name and email');
select columns_are('live_read','people',array['id','first_name','last_name','email','role','avatar'],'People projection contains only approved fields');
select ok(not has_table_privilege('clearway_live_reader','public.clients','SELECT'),'Reader has no source table SELECT');
select ok(not has_column_privilege('clearway_live_reader','public.team_members','google_refresh_token','SELECT'),'Reader has no Google token column SELECT');
select ok(not has_column_privilege('clearway_live_view_owner','public.team_members','google_refresh_token','SELECT'),'View owner cannot read Google tokens either');
select ok(not has_column_privilege('clearway_live_view_owner','public.engagements','financial_total','SELECT'),'View owner cannot read financial columns');
select ok((select bool_and(not rolsuper and not rolbypassrls and not rolinherit) from pg_roles where rolname in('clearway_live_reader','clearway_live_view_owner')),'Both roles lack bypass, superuser and inherited privileges');
select ok((select not rolcanlogin from pg_roles where rolname='clearway_live_view_owner'),'View owner cannot log in');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname in('clients','engagements','engagement_elements','events','people','person_emails','person_organizations','team_members')),'Installer preserves existing source RLS and force flags');
set local role clearway_live_reader;
select is((select count(*)::integer from live_read.clients),1,'Deleted clients are hidden');
select is((select count(*)::integer from live_read.engagements),1,'Deleted engagements are hidden');
select is((select count(*)::integer from live_read.engagement_elements),1,'Deleted elements are hidden');
select is((select count(*)::integer from live_read.events),1,'Deleted events are hidden');
select is((select count(*)::integer from live_read.people),1205,'Deleted people are hidden without a 1000-row ceiling');
select is((select count(*)::integer from live_read.person_emails),1,'Deleted email addresses are hidden');
select is((select count(*)::integer from live_read.person_organizations),1205,'Deleted organizations links are hidden');
select is((select count(*)::integer from live_read.team_members),1,'Deleted team members are hidden');
select throws_ok('select * from public.clients','42501',null,'Reader cannot bypass the view filter through a source table');
select throws_ok('select google_refresh_token from public.team_members','42501',null,'Reader cannot query source Google tokens');
select throws_ok('select google_refresh_token from live_read.team_members','42703',null,'Projection has no Google token field');
select throws_ok('select notes from live_read.people','42703',null,'Projection has no notes');
select throws_ok('select wave_access_token from live_read.team_members','42703',null,'Projection has no finance sync token');
select throws_ok('select financial_total from live_read.engagements','42703',null,'Projection has no financial totals');
select throws_ok($$insert into live_read.clients(id,name) values(gen_random_uuid(),'Must fail')$$,'42501',null,'Reader cannot insert through an updatable view');
select throws_ok($$update live_read.people set first_name='Must fail'$$,'42501',null,'Reader cannot update through an updatable view');
select throws_ok('delete from live_read.events','42501',null,'Reader cannot delete through a view');
select throws_ok('set role clearway_live_view_owner','42501',null,'Reader cannot become the view owner');
select throws_ok('create table public.reader_escape(id integer)','42501',null,'Reader cannot create source objects');
reset role;
select * from finish();
rollback;
